878	    int32_t n = 0;
879	
880	    if (!view->rot_labels || view->font == NULL || view->label_col.count <= 0) {
881	        for (i = 0; i < VMAP_ROT_LABEL_MAX; i++) {
882	            lv_obj_add_flag(view->rot_label[i], LV_OBJ_FLAG_HIDDEN);
883	        }
884	        view->rot_label_n = 0;
885	        return;
886	    }
887	
888	    for (i = 0; i < view->label_col.count && n < VMAP_ROT_LABEL_MAX; i++) {
889	        const vmap_label_cand_t * it = &view->label_col.items[i];
890	        const double dx = (double)it->x - (double)pivot_x;
891	        const double dy = (double)it->y - (double)pivot_y;
892	        const int32_t rx = (int32_t)lround((double)view->rw / 2.0
893	            + (c * dx - s * dy));
