10	/**
11	 * @brief vmap geo haversine m。
12	 */
13	double vmap_geo_haversine_m(double lon1, double lat1, double lon2, double lat2)
14	{
15	    const double r = 6371000.0;
16	    const double dlat = (lat2 - lat1) * M_PI / 180.0;
17	    const double dlon = (lon2 - lon1) * M_PI / 180.0;
18	    const double lat1r = lat1 * M_PI / 180.0;
19	    const double lat2r = lat2 * M_PI / 180.0;
20	    const double a = sin(dlat / 2.0) * sin(dlat / 2.0)
21	        + cos(lat1r) * cos(lat2r) * sin(dlon / 2.0) * sin(dlon / 2.0);
22	
23	    return 2.0 * r * asin(fmin(1.0, sqrt(a)));
24	}
25	
26	/**
27	 * @brief vmap geo bearing deg。
28	 */
29	float vmap_geo_bearing_deg(double lon1, double lat1, double lon2, double lat2)
30	{
31	    const double lat1r = lat1 * M_PI / 180.0;
32	    const double lat2r = lat2 * M_PI / 180.0;
33	    const double dlon = (lon2 - lon1) * M_PI / 180.0;
34	    const double y = sin(dlon) * cos(lat2r);
35	    const double x = cos(lat1r) * sin(lat2r)
36	        - sin(lat1r) * cos(lat2r) * cos(dlon);
37	    float brg = (float)(atan2(y, x) * 180.0 / M_PI);
38	
39	    if (brg < 0.0f) {
40	        brg += 360.0f;
41	    }
42	    return brg;
43	}
44	
45	/**
46	 * @brief vmap geo angle delta deg。
47	 */
48	float vmap_geo_angle_delta_deg(float from_deg, float to_deg)
49	{
50	    float d = to_deg - from_deg;
51	
52	    while (d > 180.0f) {
53	        d -= 360.0f;
54	    }
55	    while (d < -180.0f) {
56	        d += 360.0f;
57	    }
58	    return d;
59	}
60	
61	/**
62	 * @brief 局部等距圆柱平面的经度尺度：cos(lat) 的**多项式近似**。
63	 *
64	 * @details 为什么不用 `cos()`：`vmap_geo_point_to_seg_m()` 在导航更新里是**逐段**
65	 *          调用的（一条 2000 段的路线每 0.5 s 扫一遍）。这颗核只有 FP32，
66	 *          **双精度超越函数是软件实现**（一次 ~5 µs），于是"每段 3 次 haversine +
67	 *          2 次 bearing"= 每段 15~20 次 FP64 三角函数 ⇒ 实测**一次投影 195 ms**
68	 *          （2026-10-28 `[gpx] navupd=`）。|lat| ≤ 80° 时四阶展开误差 <1e-4，
69	 *          对 35~50 m 的偏航判据完全够用。
70	 */
71	static double vmap_geo_cos_deg(double deg)
72	{
73	    const double x = deg * (M_PI / 180.0);
74	    const double x2 = x * x;
75	
76	    return 1.0 - x2 * 0.5 + x2 * x2 * (1.0 / 24.0)
77	        - x2 * x2 * x2 * (1.0 / 720.0);
78	}
79	
80	#define VMAP_GEO_M_PER_DEG_LAT 110540.0
81	
82	/**
83	 * @brief vmap geo point to seg m。
84	 *
85	 * @note 用局部等距圆柱平面算距离与投影参数（短段误差 <0.1%）。**不要再改回
86	 *       haversine + bearing**：那是逐段 FP64 三角函数的开销，见上面 cos 近似的说明。
87	 */
88	double vmap_geo_point_to_seg_m(double px, double py,
89	    double ax, double ay, double bx, double by, double * t_out)
90	{
91	    const double kx = 111320.0 * vmap_geo_cos_deg(ay);
92	    const double vx = (bx - ax) * kx;
93	    const double vy = (by - ay) * VMAP_GEO_M_PER_DEG_LAT;
94	    const double wx = (px - ax) * kx;
95	    const double wy = (py - ay) * VMAP_GEO_M_PER_DEG_LAT;
96	    const double seg2 = vx * vx + vy * vy;
97	    double t = 0.0;
98	
99	    if (seg2 > 1e-6) {
100	        t = (wx * vx + wy * vy) / seg2;
101	        if (t < 0.0) {
102	            t = 0.0;
103	        } else if (t > 1.0) {
104	            t = 1.0;
105	        }
106	    }
107	
108	    if (t_out) {
109	        *t_out = t;
110	    }
111	
112	    {
113	        const double dx = wx - vx * t;
114	        const double dy = wy - vy * t;
115	
116	        return sqrt(dx * dx + dy * dy);
117	    }
118	}
