161	/**
162	 * @brief vmap geo project polyline m。
163	 */
164	double vmap_geo_project_polyline_m(const double * lons, const double * lats,
165	    uint32_t n, double lon, double lat, uint32_t * seg_index, double * t_on_seg)
166	{
167	    double best_d = 1e18;
168	    uint32_t best_i = 0;
169	    double best_t = 0.0;
170	
171	    if (!lons || !lats || n < 2) {
172	        if (seg_index) {
173	            *seg_index = 0;
174	        }
175	        if (t_on_seg) {
176	            *t_on_seg = 0.0;
177	        }
178	        return 1e18;
179	    }
180	
181	    for (uint32_t i = 0; i + 1 < n; i++) {
182	        double t = 0.0;
183	        const double d = vmap_geo_point_to_seg_m(lon, lat,
184	            lons[i], lats[i], lons[i + 1], lats[i + 1], &t);
185	
186	        if (d < best_d) {
187	            best_d = d;
188	            best_i = i;
189	            best_t = t;
190	        }
191	    }
192	
193	    if (seg_index) {
194	        *seg_index = best_i;
195	    }
196	    if (t_on_seg) {
197	        *t_on_seg = best_t;
198	    }
199	    return best_d;
200	}
